head.script:
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[dataList > M > getFusionChartSimpleData]<br/>DataList 모듈의 데이터를 FusionChart 의 Simple 모드인 simgleSeries, multiSeries Chart 의 JSON 데이터로 반환합니다.",
    "validation" : [
        "chartType(필수) 파라미터로 반환되는 JSON 데이터 종류를 FusionChart 의 chartType 속성값 중 하나로 설정합니다.",
        "labelNode(필수) 파라미터로 FusionChart 의 Label 데이터로 사용될 Column 의 ID 를 설정합니다.",
        "seriesNode(필수) 파라미터로 FusionChart 의 Series 데이터로 사용될 Column 의 ID 를 설정합니다.",
        "파라미터에 만족하는 형태로 FusionChart 의 JSON 데이터를 반환합니다.",
        "반환값으로 파라미터에 만족하는 형태로 FusionChart 의 JSON 데이터를 반환합니다.",
        "chartType 파라미터의 Chart 타입이 singleSeries 또는 multiSeries 인지에 따라 반환되는 JSON 데이터의 형식이 달라집니다.",
        "FusionChart 컴포넌트와 바인드 되지 않아도 JSON 데이터를 반환합니다.",
    ]
}



scwin.onpageload = function () {
    // Global DataList 생성 호출
    $c.gcm.createCommonDatalist();

    // comp 초기 생성
    scwin.comp_init();

    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);
};



// comp 생성
scwin.comp_init = async function () {   
    // 기존 target 있으면 삭제
    if (typeof target1 !== 'undefined') {
        $p.data.remove("target1");
    }

    if (typeof gridView1 !== 'undefined') {
        gridView1.remove();
    }    

    // // 조건 설정       
    // let properties = {

    // };    

    // let cList = $c.gcm.createCList(properties);

    // // 이벤트 설정
    // let eList = $c.gcm.createEList([""]);      

    // target 생성    
    let grp_comp = document.querySelector('.tc_group_basic');
    let strTarget = '';
    // let strFusionChart = '';
    let strNameSpace = $c.gcm.getNameSpace();

    strTarget += '<w2:dataList ' + strNameSpace + ' id="target1" baseNode="list" repeatNode="map">';        	
	strTarget += '<w2:columnInfo>'
	strTarget += '<w2:column id="series" name="series" dataType="text"></w2:column>'
	strTarget += '<w2:column id="label" name="label" dataType="text"></w2:column>'
    strTarget += '<w2:column id="quarter" name="quarter" dataType="text"></w2:column>'
	strTarget += '<w2:column id="value" name="value" dataType="number"></w2:column>'
	strTarget += '</w2:columnInfo>'
	strTarget += '<w2:data use="true">'
	strTarget += '<w2:row>'
	strTarget += '<series><![CDATA[First half]]></series>'
	strTarget += '<label><![CDATA[2013]]></label>'
    strTarget += '<quarter><![CDATA[Q1]]></quarter>'
	strTarget += '<value><![CDATA[390]]></value>'
	strTarget += '</w2:row>'
	strTarget += '<w2:row>'
	strTarget += '<series><![CDATA[Second half]]></series>'
	strTarget += '<label><![CDATA[2013]]></label>'
    strTarget += '<quarter><![CDATA[Q2]]></quarter>'
	strTarget += '<value><![CDATA[440]]></value>'
	strTarget += '</w2:row>'
	strTarget += '<w2:row>'
	strTarget += '<series><![CDATA[First half]]></series>'
	strTarget += '<label><![CDATA[2014]]></label>'
    strTarget += '<quarter><![CDATA[Q3]]></quarter>'
	strTarget += '<value><![CDATA[420]]></value>'
	strTarget += '</w2:row>'
	strTarget += '<w2:row>'
	strTarget += '<series><![CDATA[Second half]]></series>'
	strTarget += '<label><![CDATA[2014]]></label>'
    strTarget += '<quarter><![CDATA[Q4]]></quarter>'
	strTarget += '<value><![CDATA[450]]></value>'
	strTarget += '</w2:row>'
	strTarget += '</w2:data>'
	strTarget += '</w2:dataList>'

    $p.data.create(strTarget);
}   



scwin.btn_getFusionChartSimpleData_onclick = function (e) {
    let chartType = par_chartType.getText();
    let labelNode = par_labelNode.getText();
    let seriesNode = par_seriesNode.getText();
    let valueNode = par_valueNode.getText();

    let jsonObject = target1.getFusionChartSimpleData(chartType, labelNode, seriesNode, valueNode);    
    let jsonString = JSON.stringify(jsonObject);   

	wf_body_bottom.getObj("scwin").setReturnValue("getFusionChartSimpleData: " + jsonString);
};
